/* Foreground, audio-only WebRTC. Signaling is restricted to approved contacts. */
(()=>{
let active=null,pc=null,stream=null,busy=false,muted=false,remoteSet=false,deadline=0,lastBeat=0,contacts=[],me=null,seen=new Set();
const panel=document.createElement('dialog');panel.style.cssText='width:min(560px,calc(100% - 24px));border:1px solid #cdded9;border-radius:18px;padding:24px;color:#193b43';panel.setAttribute('aria-label','Internet voice calls');document.body.append(panel);
const top=document.createElement('button');top.className='btn';top.textContent='Voice calls';document.querySelector('.top').append(top);
const audio=document.createElement('audio');audio.autoplay=true;audio.playsInline=true;document.body.append(audio);
let status='Both people must keep the app open. Uses internet, not phone credit. Some networks cannot connect without a relay (TURN).';
async function api(path,body){const r=await fetch('/api/calls/'+path,{method:body?'POST':'GET',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Call request failed');return v}
function show(){if(!panel.open)panel.showModal();draw()}
function draw(){panel.innerHTML='<h2>Internet voice calls</h2><p id="voice-status" role="status"></p><div id="voice-controls" class="actions"></div><h3>Recent calls</h3><div id="voice-history"></div><button class="btn" id="voice-close">Close panel</button>';panel.querySelector('#voice-status').textContent=status;const box=panel.querySelector('#voice-controls');
function button(label,fn){const b=document.createElement('button');b.className='btn';b.textContent=label;b.disabled=busy;b.onclick=fn;box.append(b)}
if(active){const other=contacts.find(c=>c.id===(active.caller===me?active.callee:active.caller));const p=document.createElement('p');p.textContent=(other?.label||'Contact')+' · '+active.state;box.append(p);if(active.state==='ringing'&&active.callee===me)button('Accept',accept);if(pc&&active.state==='accepted'){button(muted?'Unmute microphone':'Mute microphone',()=>{muted=!muted;stream?.getAudioTracks().forEach(t=>t.enabled=!muted);draw()});button('Play audio',()=>audio.play().catch(()=>{status='Tap Play audio again to allow playback';draw()}))}button(active.state==='ringing'&&active.callee===me?'Decline':'End call',()=>end('Call ended'))}
else{const select=document.createElement('select');select.setAttribute('aria-label','Contact to call');contacts.forEach(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=c.label+' · '+c.role;select.append(o)});box.append(select);button('Voice call',()=>start(select.value))}
for(const c of history){const p=document.createElement('p'),other=contacts.find(x=>x.id===(c.caller===me?c.callee:c.caller));p.textContent=(other?.label||'Contact')+' · '+c.state+' · '+new Date(c.created).toLocaleString();panel.querySelector('#voice-history').append(p)}panel.querySelector('#voice-close').onclick=()=>panel.close()}
let history=[];
function cleanup(){pc?.close();pc=null;stream?.getTracks().forEach(t=>t.stop());stream=null;audio.srcObject=null;remoteSet=false;muted=false;deadline=0;lastBeat=0}
async function end(message){const id=active?.id;cleanup();active=null;status=message;draw();if(id)try{await api('end',{id})}catch{status=message+'. Server update unconfirmed; session will expire.';draw()}}
async function setup(){if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection)throw Error('Microphone calling is unavailable in this browser. Use a current browser over HTTPS.');stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});for(const track of stream.getTracks())pc.addTrack(track,stream);pc.ontrack=e=>{audio.srcObject=e.streams[0]||new MediaStream([e.track]);audio.play().catch(()=>{status='Audio playback needs a tap on Play audio.';draw()})};pc.onconnectionstatechange=()=>{if(!pc)return;if(pc.connectionState==='connected'){deadline=0;status='Connected · internet audio';draw()}else if(pc.connectionState==='failed'){end('Connection failed. This network may need a TURN relay.')}else if(pc.connectionState==='disconnected'){deadline=Date.now()+15000;status='Connection interrupted. Reconnecting…';draw()}}}
async function local(type){const current=pc;await current.setLocalDescription(await(type==='offer'?current.createOffer():current.createAnswer()));await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{current.removeEventListener('icegatheringstatechange',check);reject(Error('Network setup timed out. Please retry.'))},12000);function check(){if(current.iceGatheringState==='complete'){clearTimeout(timer);current.removeEventListener('icegatheringstatechange',check);resolve()}}current.addEventListener('icegatheringstatechange',check);check()});return {type:current.localDescription.type,sdp:current.localDescription.sdp}}
async function start(recipient){if(!recipient||busy||active)return;busy=true;status='Requesting microphone and preparing call…';draw();try{await setup();const offer=await local('offer'),r=await api('start',{recipient,offer});active={id:r.id,caller:me,callee:recipient,state:'ringing'};deadline=Date.now()+65000;status='Calling… waiting for your contact to accept.'}catch(e){cleanup();status=e.message}finally{busy=false;draw()}}
async function accept(){if(busy||!active)return;busy=true;draw();try{await setup();await pc.setRemoteDescription(JSON.parse(active.offer));remoteSet=true;const answer=await local('answer');await api('answer',{id:active.id,answer});active.state='accepted';deadline=Date.now()+30000;status='Connecting audio…'}catch(e){await end(e.message)}finally{busy=false;draw()}}
let polling=false;
async function poll(){if(polling||busy)return;polling=true;try{const r=await api('poll');me=r.me;contacts=r.contacts;history=r.calls;const current=active&&r.calls.find(c=>c.id===active.id);if(active){if(!current||!['ringing','accepted'].includes(current.state)){cleanup();active=null;status='Call '+(current?.state||'unavailable')}else{active=current;if(pc&&current.state==='accepted'&&current.answer&&!remoteSet){await pc.setRemoteDescription(JSON.parse(current.answer));remoteSet=true;deadline=Date.now()+30000;status='Connecting audio…'}if(pc&&current.state==='accepted'&&Date.now()-lastBeat>10000){await api('heartbeat',{id:current.id});lastBeat=Date.now()}}}else{const incoming=r.calls.find(c=>c.callee===me&&c.state==='ringing');if(incoming&&!seen.has(incoming.id)){seen.add(incoming.id);active=incoming;status='Incoming voice call. Accept to enable your microphone.';show()}}
if(deadline&&Date.now()>deadline)await end('Call timed out. Check both devices and your network.');if(panel.open)draw();
}catch(e){if(active)await end('Connection to call service lost. Call stopped.');else if(panel.open){status=e.message;draw()}}finally{polling=false}}
top.onclick=async()=>{show();await poll()};panel.addEventListener('cancel',()=>{});
const previousReset=window.fnMessages?.reset;if(previousReset)window.fnMessages.reset=()=>{end('Signed out');previousReset()};window.addEventListener('pagehide',()=>{cleanup()});setInterval(poll,2500);poll();
})();
